-- v992: контент курса «Адаптация» — День 3 · Продукт: база. Сгенерировано gen-academy-adaptation.mjs

INSERT INTO academy_modules (id, course_id, sort, title, intro, gate, active) VALUES
 ($sd$a0000000-0000-0000-0002-000000000003$sd$, $sd$c0000000-0000-0000-0000-000000000002$sd$, 40, $sd$День 3 · Продукт: база$sd$, $sd$Что продаём, кому и какую боль закрываем. Сегменты, кейсы, цифры и то, что клиент думает о нас на каждом шаге.$sd$, $sd${"title":"Зачёт дня 3","tasks":["Объяснение за 60 секунд: описываешь продукт простыми словами «как директору небольшой дистрибьюторской компании»","Разбор кейса Nestle или Grizzly: 3 проблемы клиента → 3 решения через платформу","Ситуация: «У нас 1С, и мы справляемся» — аргументируешь ценность интеграции и автоматизации полевых процессов","Называешь сегменты A/B/C с чеком и способом продажи, объясняешь разницу Van Sales / PreSale"],"result":"Можешь просто и убедительно объяснить, что продаёшь и какую боль закрываешь."}$sd$::jsonb, true)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, sort = EXCLUDED.sort, title = EXCLUDED.title, intro = EXCLUDED.intro, gate = EXCLUDED.gate, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000301$sd$, $sd$a0000000-0000-0000-0002-000000000003$sd$, 10, $sd$Что мы продаём$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Что такое Sales Doctor одной фразой?","options":["CRM для любого бизнеса","Платформа автоматизации полного цикла дистрибуции","Бухгалтерская программа","Мобильное приложение для курьеров"],"correct":1},{"q":"Что получает торговый представитель?","options":["Дашборды дебиторки","Заказы с телефона, маршруты, отчётность","Контроль автопарка","Прогнозы спроса"],"correct":1},{"q":"На сколько сокращается время обработки заказов?","options":["На 10 %","На 40 %","На 70 %","В 2 раза"],"correct":1},{"q":"Какая боль НЕ из нашего списка?","options":["Потери заказов","Слепая логистика","Ручная отчётность","Подбор персонала"],"correct":3},{"q":"На сколько дешевеет логистика с системой?","options":["На 5 %","На 15–20 %","На 50 %","Не влияет"],"correct":1}]$sd$::jsonb, $sd$<p><b>Sales Doctor</b> — IT-платформа для автоматизации полного цикла дистрибуции: от заявки торгового представителя до доставки и аналитики.</p>
<h4>Три модуля — три пользователя</h4>
<table class="tbl"><thead><tr><th>Кому</th><th>Что даёт</th></tr></thead><tbody>
<tr><td><b>Торговым представителям</b></td><td>Маршруты, электронные заказы с телефона (в 2 клика), отчётность, работа офлайн в поле, полноценное приложение iOS и Android</td></tr>
<tr><td><b>Логистам / экспедиторам</b></td><td>Оптимизация маршрутов доставки, контроль автопарка, GPS-трекинг</td></tr>
<tr><td><b>Руководителю</b></td><td>Дашборды KPI в реальном времени, контроль дебиторки, прогнозы</td></tr>
</tbody></table>
<h4>Какие боли закрываем</h4>
<ul>
<li><b>Потери заказов</b> — агент не донёс заявку, магазин остался без поставки.</li>
<li><b>«Слепая» логистика</b> — водитель «наворачивает круги», возвраты, левые рейсы, перерасход ГСМ.</li>
<li><b>Ручная отчётность</b> — руководитель тратит часы на сверки в Excel.</li>
<li><b>Низкая оборачиваемость</b> и отсутствие прозрачности между агентами, логистами и руководителем.</li>
</ul>
<h4>Цифры, которые называем</h4>
<div class="kpis"><div><b>−40 %</b><span>время обработки заказов</span></div><div><b>до 5 %</b><span>ошибки в заказах</span></div><div><b>−15–20 %</b><span>затраты на логистику</span></div><div><b>+20–30 %</b><span>продажи на агента</span></div></div>
<h4>Ещё продукты компании</h4>
<p>IBOX — второй основной продукт; дополнительные продажи — интеграция и внедрение (пакеты стандарт / стандарт плюс / премиум), телеграм-боты; удержание — абонентская плата, подписка.</p>$sd$, $sd$[{"t":"Продуктовая матрица","u":"https://docs.google.com/spreadsheets/d/1Ox7wXUDzHYmhBgJJIReioitJCdirdRb4wehkcFMB1SQ/edit"},{"t":"Вопросы для распаковки продукта","u":"https://docs.google.com/document/d/1TBwsKcWhPPv_XxqYzpad0ENkrqE2mpfx5za2109v600/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000302$sd$, $sd$a0000000-0000-0000-0002-000000000003$sd$, 20, $sd$Сегменты A / B / C и как им продаём$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Характеристики B-сегмента:","options":["150+ пользователей, $7 000/год","10–50 пользователей, $1 000–1 500/год","До 5 пользователей, $420/год","Только ритейл"],"correct":1},{"q":"Какую долю выручки даёт B-сегмент?","options":["30 %","50 %","83 %","100 %"],"correct":2},{"q":"Как продаём C-сегменту?","options":["Офлайн-встречи","Мастер-класс / видео-презентация","Только через партнёров","Не продаём"],"correct":1},{"q":"Van Sales — это…","options":["Продажа через сайт","Агент продаёт и сразу привозит товар","Сначала заказ, потом доставка","Продажа с фургона на рынке"],"correct":1},{"q":"Пример клиента A-сегмента:","options":["Nestle","Небольшой ИП","Розничный магазин","Кафе"],"correct":0}]$sd$::jsonb, $sd$<table class="tbl"><thead><tr><th>Сегмент</th><th>Кто это</th><th>Чек и цикл</th><th>Как продаём (КЭВ)</th></tr></thead><tbody>
<tr><td><b>A</b> — крупный</td><td>Компании, продающие товары в магазины по всей стране; 150+ пользователей (пример — Nestle)</td><td>~ $7 000 / год, долгий цикл, несколько ЛПР</td><td>Офлайн-встречи, key account</td></tr>
<tr><td><b>B</b> — средний</td><td>Команда 10–50 пользователей</td><td>$1 000–1 500 / год, быстрое решение</td><td>Онлайн-презентация / мастер-класс</td></tr>
<tr><td><b>C</b> — малый</td><td>Небольшие дистрибьюторы</td><td>~ $420 / год, много сделок</td><td>Мастер-класс / видео-презентация, автоматизация</td></tr>
</tbody></table>
<div class="callout"><b>B-сегмент — основной источник выручки: 83 %.</b> Быстрое принятие решений, низкая сложность сделок, высокая конверсия. Норма дня «30 звонков в A/B» — про него.</div>
<h4>Модель торговли клиента — критично для конфигурации</h4>
<ul>
<li><b>Van Sales</b> — агент продаёт и сразу привозит товар. Агент = экспедитор.</li>
<li><b>PreSale</b> — сначала заказ, потом доставка отдельно. Нужны и агенты, и логистика.</li>
</ul>
<h4>Идеальный клиент</h4>
<p>FMCG-дистрибьютор с торговой командой в поле, заявки в Excel / 1С / на бумаге, есть потери заявок или накладки по доставке, руководитель хочет видеть KPI в цифрах.</p>$sd$, $sd$[{"t":"КОМУ — ЧТО — КАК","u":"https://docs.google.com/spreadsheets/d/1N5rGHGD9qXIOII8dOIG211n_mscYjUNUIRC6XEw0_nI/edit"},{"t":"Анализ FMCG","u":"https://docs.google.com/spreadsheets/d/1jl8qDwRXazTWVbBYDtGd4XxsmTSqHSYNi2oMKxobbh4/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000303$sd$, $sd$a0000000-0000-0000-0002-000000000003$sd$, 30, $sd$Кейсы и цифры$sd$, $sd$10 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Какой ROI у Grizzly и за какой срок?","options":["100 % за год","214 % за 8 месяцев","50 % за 3 месяца","300 % за 2 года"],"correct":1},{"q":"Сколько пользователей у Nestle Кыргызстан?","options":["15","50","150+","1 000"],"correct":2},{"q":"Какой результат у Сайрам нан?","options":["Оборачиваемость +35 %","Логистика −50 %","Штат −20 %","ROI 500 %"],"correct":0},{"q":"Формула рассказа кейса:","options":["Цена → скидка → договор","Ситуация «до» → что внедрили → цифра «после»","Модули → тарифы → бонус","Проблема → конкурент → мы"],"correct":1}]$sd$::jsonb, $sd$<p>Три кейса, которые ты должен уметь рассказать за 30 секунд каждый.</p>
<div class="cases">
<div><b>Nestle Кыргызстан</b><span>150+ пользователей. Крупный FMCG-производитель, A-сегмент. Пример масштаба и надёжности.</span></div>
<div><b>Grizzly</b><span>Внедрение за 8 месяцев, ROI 214 %. Рост продаж на 30 %. Главный кейс для B-сегмента: «до» — заявки, логистика, доставка в разных системах; «после» — единая система, меньше ручной работы, больше контроля.</span></div>
<div><b>Сайрам нан</b><span>Рост оборачиваемости на 35 %.</span></div>
</div>
<h4>Как использовать кейс в разговоре</h4>
<ul>
<li>Кейс подбирается под категорию клиента: крупному — Nestle, среднему — Grizzly.</li>
<li>Формула: <b>ситуация «до» → что внедрили → цифра «после»</b>.</li>
<li>Не обещай чужие цифры как гарантию — «у Grizzly было так, давайте посчитаем у вас».</li>
</ul>
<h4>Разбор кейса — упражнение на зачёт</h4>
<p>На примере Nestle или Grizzly назови <b>3 проблемы</b> клиента и <b>3 способа</b> их решения через платформу. Например: теряются заявки → электронные заказы с телефона; водители «кружат» → маршрутизация; директор не видит команду → дашборд KPI.</p>$sd$, $sd$[{"t":"Усилители доверия","u":"https://docs.google.com/document/d/1irHvZbYU3NdwE4FpZLyNxkWZf3PjwaK3Y7JPk1TALaw/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000304$sd$, $sd$a0000000-0000-0000-0002-000000000003$sd$, 40, $sd$Что думает клиент: CJM$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Главный страх клиента при общении с менеджером:","options":["Высокая цена","Что менеджер впаривает и не понимает дистрибуцию","Долгое внедрение","Нет приложения"],"correct":1},{"q":"Что злит клиента на этапе КП?","options":["Слишком быстро прислали","Прислали не то и не те цифры, что обсуждали","Много страниц","Нет логотипа"],"correct":1},{"q":"Чего боится клиент в договоре?","options":["Что он слишком короткий","Скрытых условий и расхождения со словами менеджера","Что нет печати","Что его не подпишут"],"correct":1},{"q":"Что делаем после оплаты, чтобы не спамить «ну что, подписали?»","options":["Ничего","Договариваемся о дате обратной связи по оплате заранее","Звоним каждый день","Пишем бухгалтеру"],"correct":1}]$sd$::jsonb, $sd$<p>Карта пути клиента показывает его страхи на каждом шаге. Зная их, ты предвосхищаешь возражения, а не отбиваешь их.</p>
<table class="tbl"><thead><tr><th>Этап</th><th>Что думает клиент</th><th>Что его злит</th><th>Что делаем</th></tr></thead><tbody>
<tr><td>Ищет информацию</td><td>«Какие программы бывают? Как выбрать поставщика, чтобы не кинули?»</td><td>Непонятное описание, плохой менеджер на выставке</td><td>Показываем, что мы порядочные: кейсы, обзоры, отзывы</td></tr>
<tr><td>Оставляет заявку</td><td>«Когда перезвонят? Не будут ли надоедать звонками?»</td><td>Не перезвонили, не дали первичную информацию</td><td>Звонок в течение 1 часа, сразу схема работы и «почему мы»</td></tr>
<tr><td>Общается с менеджером</td><td>«Скажет правду или будет впаривать? Понимает ли он дистрибуцию?»</td><td>Не выполняет обещания, не слышит клиента, спамит</td><td>Квалификация = диагностика, язык клиента, обещания в срок</td></tr>
<tr><td>Получает КП</td><td>«Есть ли дешевле? Скрытые платежи?»</td><td>Прислали не то, что обсуждали, не те цифры</td><td>Персональное КП с именем и нюансами разговора, блок «почему мы»</td></tr>
<tr><td>Договор и счёт</td><td>«Та ли цена? Сроки внедрения? Что, если задержат? Конфиденциальность данных?»</td><td>Пункты договора расходятся со словами менеджера, платные услуги «вдруг»</td><td>Все условия проговорены до договора, сроки и гарантии в тексте</td></tr>
<tr><td>Оплата</td><td>«Правильный ли выбор?»</td><td>Спам «ну что, подписали?»</td><td>Договариваемся о дате обратной связи по оплате в разговоре</td></tr>
<tr><td>Внедрение</td><td>«Внедрят ли вовремя? Саботаж команды?»</td><td>Не приехали, тянут время</td><td>Передача в производство с чёткими сроками</td></tr>
<tr><td>Пользуется</td><td>«Что если сломается? Как быстро реагируют?»</td><td>Забыли про клиента</td><td>Звонок после сделки, сбор ОС и NPS, запрос рекомендаций</td></tr>
</tbody></table>$sd$, $sd$[{"t":"ZG CJM карта · аватар","u":"https://docs.google.com/spreadsheets/d/1C77oJkfS0MKNmyVQwe7H6DvXt2uw4gPMzo63bezixWs/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;
